from pathlib import Path
import json

import joblib
import pandas as pd
import streamlit as st


BASE_DIR = Path(__file__).resolve().parent
MODEL_FILE = BASE_DIR / "spam_model.joblib"
METRICS_FILE = BASE_DIR / "metrics.json"

st.set_page_config(
    page_title="SpamShield",
    page_icon="🛡️",
    layout="centered",
)


@st.cache_resource
def load_model():
    # Load only the model generated by your own training script.
    return joblib.load(MODEL_FILE)


st.title("🛡️ SpamShield")
st.write("Check whether an English SMS message looks like spam.")

if not MODEL_FILE.exists() or not METRICS_FILE.exists():
    st.error("Train the model first: python train.py")
    st.stop()

model = load_model()
metrics = json.loads(METRICS_FILE.read_text(encoding="utf-8"))

with st.form("message_form"):
    message = st.text_area(
        "Enter an SMS message",
        height=150,
        placeholder="Type or paste a message here...",
        max_chars=5000,
    )

    submitted = st.form_submit_button(
        "Check message",
        use_container_width=True,
    )

if submitted:
    if not message.strip():
        st.warning("Please enter a message.")
    else:
        prediction = model.predict([message.strip()])[0]

        if prediction == "spam":
            st.error("🚨 Prediction: Spam")
        else:
            st.success("✅ Prediction: Not spam")

        st.caption(
            "This prediction can be wrong. A 'Not spam' result "
            "does not verify links, senders, or payment requests."
        )

with st.expander("Example messages"):
    st.write("Try these individually:")
    st.code(
        "Congratulations! You won a free prize. Call now to claim.",
        language=None,
    )
    st.code(
        "Hey, are we meeting at the library after class?",
        language=None,
    )

with st.expander("Model evaluation"):
    st.caption(
        "Measured on the held-out 20% test split of the "
        "deduplicated UCI dataset."
    )

    col1, col2 = st.columns(2)
    col1.metric("Accuracy", f"{metrics['accuracy']:.1%}")
    col2.metric("Spam F1", f"{metrics['spam_f1']:.1%}")

    col3, col4 = st.columns(2)
    col3.metric("Spam precision", f"{metrics['spam_precision']:.1%}")
    col4.metric("Spam recall", f"{metrics['spam_recall']:.1%}")

    st.write(
        f"Training messages: {metrics['training_messages']} | "
        f"Test messages: {metrics['test_messages']}"
    )

    matrix = pd.DataFrame(
        metrics["confusion_matrix"],
        index=["Actual not spam", "Actual spam"],
        columns=["Predicted not spam", "Predicted spam"],
    )

    st.write("Confusion matrix")
    st.dataframe(matrix, use_container_width=True)

st.caption("Built with Python, scikit-learn, and Streamlit.")